-- =====================================================================
-- 开源安全评分看板 · gcheck 三指标明细展示配置更新
-- 指标：PINNED_DEP（依赖锁定）/ FUZZING（模糊测试）/ BINARY_ARTIFACTS（二进制制品）
-- 表：dm_rd_efc_security_metric_detail_conf（单行压缩 conf_json）
-- 依据：gcheck 严格口径（OSSF Scorecard v5.5.0 GitCode 离线适配）+ 明细原型 15/20/21 号页；
--       FUZZING 按 Q-051 答复移除名单比对提示；BINARY_ARTIFACTS 2026-10-09 口径切换为内容魔数识别。
-- 执行后约 5 分钟内生效（服务端 5 分钟 TTL 缓存），无需发版。
-- 同步：openlibing-ops classpath 内置默认 JSON（security/detail-conf/）与
--       openlibing-docs 的 detail-conf-init.sql 均已同步同一份配置。
-- 生成：ai-assisted 2026-10-10
-- 修订：ai-assisted 2026-10-13 FUZZING when 条件修复——引擎 when 操作数不支持字符串字面量
--       （"none" 会被当 raw 路径解析为 null），改用隐藏 summary 计算值 isNone（#map 数字 1/0）
--       + when "isNone=1" 数字比较。三处同步：本文件 / classpath FUZZING.json / detail-conf-init.sql。
-- 修订：ai-assisted 2026-10-14 PINNED_DEP 移除「信号」展示项（failItems 卡片字段、依赖明细
--       表格列及 searchText）——信号仅镜像类条目有值且含义与判定依据重复，不再展示；
--       规则/说明文案中的 signal 字眼同步改为大白话（变量引用 / 裸名引用等口径限制）。
-- 修订：ai-assisted 2026-10-14 判据汇总表格「合规率」列补 %——引擎 #pct 新增可选第 3 参数
--       字面后缀（#pct:$ok,$hit,% → 85.7%），既有两参数用法不受影响。
-- 修订：ai-assisted 2026-10-16 PINNED_DEP 移除「依赖明细」表格分组——全量明细已迁移至
--       独立分页接口 /security/pinned-dep-list（表 dwi_rd_efc_security_pinned_dep_detail），
--       metric-detail 响应保留判据汇总与不满足项卡片。
-- =====================================================================

UPDATE openlibing.dm_rd_efc_security_metric_detail_conf
SET conf_json = '{"rule":{"brief":"检查 CI/CD 与构建文件中的依赖是否固定到不可变版本（gcheck 严格口径，对齐 OSSF Scorecard v5.5.0 pinned-dependencies）：容器镜像须以 @sha256 摘要引用、pip 安装须 --require-hashes、npm 须 npm ci 或固定哈希、go install / go get 须固定版本、下载即执行须按哈希固定。workflow action 引用默认不检测。","formula":"得分 = 已固定依赖数 / 依赖总数 × 10","conditions":[{"label":"已固定","value":"镜像 @sha256 摘要 / pip --require-hashes / npm ci / go 固定版本 / 下载固定到 40 位提交 SHA"},{"label":"未固定","value":"浮动 tag（如 latest）、仅版本号无哈希、可变分支引用"},{"label":"口径问题条目","value":"判定依据标注变量引用、裸名引用、构建阶段别名、本地路径等的条目没有可通过的整改路径，属口径问题，不开整改单"}],"naCondition":"未识别到任何依赖（not-applicable）、无默认分支 / checkout 失败 / gcheck 超时等无法运行时为 NA，不计分子分母。","notes":["2026-10-09 起生产数据来自 security_gcheck_scan.py（gcheck 离线扫描批次）","workflow action 引用默认不检测（GitCode 平台不进行 actions 版本依赖扫描，官方插件裸名引用没有可固定的版本位）"]},"summary":[{"key":"unpinned","hidden":true,"value":"#sub:$total_count,$pinned_count"},{"key":"rate","hidden":true,"value":"#pct:$pinned_count,$total_count"},{"label":"总依赖数","value":"$total_count"},{"label":"已固定","value":"$pinned_count","level":"#eq:$pinned_count:$total_count:success"},{"label":"未固定","value":"#tpl:{s.unpinned}","level":"#gt:$s.unpinned:0:error"},{"label":"合规率","value":"#tpl:{s.rate}%","level":"#lt:$pinned_count:$total_count:warning"}],"failNote":"#tpl:评分：已固定 {pinned_count} / 总依赖数 {total_count} × 10 = {score}　｜　严格口径：镜像须 @sha256 摘要、pip 须 --require-hashes，仅固定版本号不算固定","failEmptyText":"全部满足：全部依赖均已按严格口径固定（镜像 @sha256 / pip --require-hashes 等）","dataNote":"分子分母 = gcheck summary 的 compliant + nonCompliant（无法判定的条目不进分子分母）。判据默认 7 项（ciAction 关闭；downloadThenRun 上游不采集「已固定」的下载条目，命中即存在不合规下载）。完整依赖明细清单（全量、不截断）走独立分页接口，本页判据汇总按主表数据统计。整改指引为空或判定依据标注口径限制（变量引用 / 裸名引用等）的条目无需整改。","failItems":{"from":"$deps","filter":{"pinned":"=false"},"card":{"title":"#tpl:未固定依赖：{file}","fields":[{"label":"依赖类型","value":"#map:$type:containerImage:容器镜像,downloadThenRun:下载即执行,goCommand:Go 命令,pipCommand:pip 命令,npmCommand:npm 命令,chocoCommand:Chocolatey,nugetCommand:NuGet/.NET,ciAction:Action 引用,unknown:未识别,*:其他"},{"label":"文件","value":"$file"},{"label":"行号","value":"#ifnull:$line:—"},{"label":"依赖引用","value":"#ifnull:$ref:—"}],"reason":"#tpl:未满足：{file} 中的依赖未按严格口径固定（{reason}）","searchText":"#tpl:{file} {type} {ref}"}},"groups":[{"key":"judge","label":"判据汇总","columns":[{"label":"判据","key":"name","type":"text"},{"label":"命中","key":"hit","type":"number"},{"label":"符合","key":"ok","type":"number"},{"label":"不符合","key":"bad","type":"number"},{"label":"合规率","key":"rate","type":"text"}],"rows":[{"name":"容器镜像","hit":"#qcount:$deps:type=containerImage","ok":"#qcount:$deps:type=containerImage,pinned=true","bad":"#qcount:$deps:type=containerImage,pinned=false"},{"name":"下载即执行","hit":"#qcount:$deps:type=downloadThenRun","ok":"#qcount:$deps:type=downloadThenRun,pinned=true","bad":"#qcount:$deps:type=downloadThenRun,pinned=false"},{"name":"Go 命令","hit":"#qcount:$deps:type=goCommand","ok":"#qcount:$deps:type=goCommand,pinned=true","bad":"#qcount:$deps:type=goCommand,pinned=false"},{"name":"pip 命令","hit":"#qcount:$deps:type=pipCommand","ok":"#qcount:$deps:type=pipCommand,pinned=true","bad":"#qcount:$deps:type=pipCommand,pinned=false"},{"name":"npm 命令","hit":"#qcount:$deps:type=npmCommand","ok":"#qcount:$deps:type=npmCommand,pinned=true","bad":"#qcount:$deps:type=npmCommand,pinned=false"},{"name":"Chocolatey","hit":"#qcount:$deps:type=chocoCommand","ok":"#qcount:$deps:type=chocoCommand,pinned=true","bad":"#qcount:$deps:type=chocoCommand,pinned=false"},{"name":"NuGet / .NET","hit":"#qcount:$deps:type=nugetCommand","ok":"#qcount:$deps:type=nugetCommand,pinned=true","bad":"#qcount:$deps:type=nugetCommand,pinned=false"}],"cellOf":{"name":{"text":"$name"},"hit":{"text":"$hit"},"ok":{"text":"$ok","level":"#gt:$ok:0:success"},"bad":{"text":"$bad","level":"#gt:$bad:0:error"},"rate":{"text":"#pct:$ok,$hit,%"}},"searchText":"#tpl:{name} {hit} {ok} {bad}"}],"emptyHint":"本仓库未识别到任何依赖（NA），或 gcheck 无法运行，无明细数据"}',
    updated_by = 'ai-assisted',
    updated_at = NOW()
WHERE metric_code = 'PINNED_DEP';

UPDATE openlibing.dm_rd_efc_security_metric_detail_conf
SET conf_json = '{"rule":{"brief":"检查仓库是否开展模糊测试活动：收录于 OSS-Fuzz 官方项目名单、workflow 中配置 ClusterFuzzLite、使用语言原生 fuzz 能力（go test fuzz / libFuzzer / atheris / cargo-fuzz / Jazzer 等），或配置 property-testing。共 17 项判据（2 项非语言 + 7 项引擎型 + 8 项属性测试），检测到的工具数量不影响评分。","formula":"阶梯计分，只取满足的最高档：OSS-Fuzz 或 ClusterFuzzLite = 10 分；语言原生 fuzz = 5 分；property-testing = 3 分；全部未检出 = 0 分。各档相互独立，不存在低档阻断。","conditions":[{"label":"OSS-Fuzz","value":"仓库收录于 OSS-Fuzz 官方项目名单（main_repo 归一化比对）"},{"label":"ClusterFuzzLite","value":"workflow 中引用 / 配置 ClusterFuzzLite"},{"label":"原生 fuzz","value":"go test fuzz、C/C++/Swift libFuzzer、python-atheris、rust cargo-fuzz、java Jazzer"},{"label":"property-testing","value":"Haskell / JS / TS / C# / F# / Erlang / Elixir / Gleam 属性测试框架"}],"naCondition":"无默认分支 / checkout 失败 / gcheck 超时等无法运行时为 NA。「全部未检出」是有效 0 分，不是 NA。","notes":["口径 = OSSF Scorecard v5.5.0 fuzzing check + property-testing=3 分阶梯扩展（Q-048 答复：8 项属性测试判据都算分）","2026-10-09 起生产数据来自 security_gcheck_scan.py（gcheck 离线扫描批次）"]},"summary":[{"key":"hitN","hidden":true,"value":"#count:$hit_criteria"},{"key":"isNone","hidden":true,"value":"#map:$tier:none:1,*:0"},{"label":"当前档位","value":"#map:$tier:oss_fuzz:OSS-Fuzz（10分）,clusterfuzzlite:ClusterFuzzLite（10分）,native_fuzz:原生 fuzz（5分）,property_testing:属性测试（3分）,none:无任何 Fuzzing 活动（0分）","level":"#map:$tier:oss_fuzz:success,clusterfuzzlite:success,native_fuzz:success,property_testing:warning,none:error"},{"label":"命中判据","value":"#tpl:{s.hitN} / 17"},{"label":"OSS-Fuzz","value":"#bool:$in_ossfuzz:已收录:未收录","level":"#bool:$in_ossfuzz:success:"},{"label":"ClusterFuzzLite","value":"#bool:$has_clusterfuzzlite:已配置:未配置"},{"label":"原生 fuzz","value":"#bool:$native_fuzz:检出:未检出"}],"failNote":"#tpl:阶梯计分：只取满足的最高档，无逐条扣分（故卡片不显示扣分值）　｜　当前 {score} 分","failEmptyText":"满分：已集成 OSS-Fuzz 或配置 ClusterFuzzLite，取最高档 10 分","dataNote":"OSS-Fuzz 判定依据 OSS-Fuzz 官方项目名单快照（main_repo 归一化比对）。原生 fuzz / property-testing 按代码特征识别（fuzz 函数 / 构建脚本 / 测试框架）。证据明细最多展示前 50 条。17 项判据全部未命中时产出仓库级未检出条目（无文件可派单），不单独铺卡。","failItems":[{"when":"isNone=1","title":"未检出任何模糊测试活动","fields":[{"label":"当前档位","value":"无任何 Fuzzing 活动（0 分）","level":"error"},{"label":"OSS-Fuzz 名单","value":"#bool:$in_ossfuzz:已收录:未收录"},{"label":"ClusterFuzzLite","value":"未配置"},{"label":"原生 fuzz","value":"未检出"},{"label":"属性测试","value":"未检出"}],"reason":"未满足：17 项判据全部未命中 —— 未检出 OSS-Fuzz 收录 / ClusterFuzzLite 配置 / 语言原生 fuzz / property-testing 任何一类模糊测试活动","searchText":"fuzzing 未检出 模糊测试"}],"groups":[{"key":"ladder","label":"阶梯判定","columns":[{"label":"台阶","key":"name","type":"text"},{"label":"档位分","key":"score","type":"number"},{"label":"是否计入","key":"used","type":"text"},{"label":"判定依据","key":"check","type":"text"}],"rows":[{"name":"集成 OSS-Fuzz","score":"10","used":"#map:$tier:oss_fuzz:计入（当前档位）,*:未计入","check":"仓库身份与 OSS-Fuzz 名单每个项目的 main_repo 归一化成小写 host/org/repo 后比对"},{"name":"配置 ClusterFuzzLite","score":"10","used":"#map:$tier:clusterfuzzlite:计入（当前档位）,*:未计入","check":"workflow 中引用 / 配置 ClusterFuzzLite"},{"name":"原生 fuzz","score":"5","used":"#map:$tier:native_fuzz:计入（当前档位）,*:未计入","check":"7 项引擎型判据命中任一：Go testing.F / LibFuzzer（C·C++·Swift）/ Atheris / cargo-fuzz / Jazzer"},{"name":"属性测试","score":"3","used":"#map:$tier:property_testing:计入（当前档位）,*:未计入","check":"8 项属性测试判据命中任一：Haskell / JS / TS / C# / F# / Erlang / Elixir / Gleam"},{"name":"无任何 Fuzzing 活动","score":"0","used":"#map:$tier:none:计入（当前档位）,*:未计入","check":"17 项判据全部未命中 —— 仓库级未检出条目（id=null、scope=repo）"}],"cellOf":{"name":{"text":"$name"},"score":{"text":"$score"},"used":{"text":"$used"},"check":{"text":"$check"}},"searchText":"#tpl:{name} {score} {check}"},{"key":"sig","label":"fuzz 集成证据","columns":[{"label":"判据","key":"crit","type":"text"},{"label":"文件","key":"file","type":"text"},{"label":"行号","key":"line","type":"text"},{"label":"代码片段","key":"snippet","type":"text"}],"rowsFrom":"$signals","cellOf":{"crit":{"text":"#map:$criterion:ossFuzz:OSS-Fuzz,clusterFuzzLite:ClusterFuzzLite,go-native:go test fuzz,c-libfuzzer:C libFuzzer,cpp-libfuzzer:C++ libFuzzer,swift-libfuzzer:Swift libFuzzer,python-atheris:Python atheris,rust-cargo-fuzz:Rust cargo-fuzz,java-jazzer:Java Jazzer,haskell-property-testing:Haskell 属性测试,javascript-property-testing:JavaScript 属性测试,typescript-property-testing:TypeScript 属性测试,csharp-property-testing:C# 属性测试,fsharp-property-testing:F# 属性测试,erlang-property-testing:Erlang 属性测试,elixir-property-testing:Elixir 属性测试,gleam-property-testing:Gleam 属性测试,*:其他"},"file":{"text":"$file"},"line":{"text":"#ifnull:$line:—"},"snippet":{"text":"#ifnull:$snippet:—"}},"searchText":"#tpl:{criterion} {file} {snippet}"}],"emptyHint":"未检出模糊测试活动（0 分）时无证据明细；NA 仓库（gcheck 无法运行）同样无明细数据"}',
    updated_by = 'ai-assisted',
    updated_at = NOW()
WHERE metric_code = 'FUZZING';

UPDATE openlibing.dm_rd_efc_security_metric_detail_conf
SET conf_json = '{"rule":{"brief":"检查仓库中是否直接提交了二进制可执行产物（gcheck 严格口径：按文件内容魔数识别，不再按文件名后缀判定）。识别 ELF / PE / Mach-O / WASM 可执行与 ar 归档等真二进制。","formula":"得分 = 10 − 二进制文件数（最低 0 分，每个文件扣 1 分）","conditions":[{"label":"命中即扣分","value":"文件内容命中魔数特征（ELF / PE / Mach-O / WASM / ar 归档），不区分目录"}],"naCondition":"无，本指标恒有得分。","notes":["2026-10-09 口径切换：由文件名后缀清单改为文件内容魔数识别（gcheck binary-artifacts），历史批次数据不可比",".gz / .zip / .pdf / .jar / .pyc 等非可执行产物不再上报","vendor / node_modules 目录照报（上游口径）"]},"params":{"unit":"1"},"summary":[{"key":"n","label":"二进制文件数","value":"$binary_count","level":"#gt:$binary_count:0:error"},{"label":"每个扣分","value":"#tpl:{p.unit}"},{"key":"total","hidden":true,"value":"#mul:$binary_count,$p.unit"},{"label":"合计扣分","value":"#tpl:-{s.total}","level":"#gt:$binary_count:0:error"},{"label":"得分公式","value":"max(0, 10 − n)"}],"failNote":"#tpl:评分：max(0, 10 − 二进制文件数 {binary_count}) = {score}　｜　逐文件累加扣分（每个 {p.unit} 分）","failEmptyText":"全部满足：按文件内容魔数识别，全仓未检出二进制可执行产物，无扣分","dataNote":"扫描全仓文件树，按文件内容魔数识别真二进制可执行产物：ELF（Linux 可执行 / 共享库）、PE（Windows exe / dll）、Mach-O（macOS 可执行）、WASM（WebAssembly 模块）、ar 归档（.a 静态库）。文件名后缀不再作为判定依据：.gz / .zip / .pdf / .jar / .pyc 等非可执行产物不上报。自动排除 .git、testdata 等目录；vendor / node_modules 目录照报（上游口径）。本指标没有 NA 条件。","failItems":{"from":"$artifact_types","card":{"title":"#tpl:检出二进制文件：{path}","fields":[{"label":"文件路径","value":"$path"},{"label":"产物类型","value":"#map:$signal:elf:ELF 可执行/共享库,pe:PE 可执行,macho:Mach-O 可执行,macho-fat-or-java-class:Mach-O fat/Java class,wasm:WASM 模块,archive:ar 归档,*:其他二进制"},{"label":"扣分","value":"#tpl:-{p.unit}","level":"error"}],"reason":"#tpl:未满足：文件 {path} 内容命中二进制魔数特征（{signal}）","searchText":"$path"}},"groups":[{"key":"bin","label":"二进制文件清单","columns":[{"label":"文件路径","key":"path","type":"text"},{"label":"产物类型","key":"type","type":"text"},{"label":"扣分","key":"ded","type":"number"}],"rowsFrom":"$artifact_types","cellOf":{"path":{"text":"$path"},"type":{"text":"#map:$signal:elf:ELF 可执行/共享库,pe:PE 可执行,macho:Mach-O 可执行,macho-fat-or-java-class:Mach-O fat/Java class,wasm:WASM 模块,archive:ar 归档,*:其他二进制"},"ded":{"text":"#tpl:-{p.unit}","level":"error"}},"searchText":"$path"}]}',
    updated_by = 'ai-assisted',
    updated_at = NOW()
WHERE metric_code = 'BINARY_ARTIFACTS';
